			int num = 1 << obj.layer;
			int cullingMask = camera.cullingMask;
			if ((num & cullingMask) == 0)
			{
				for (int i = 0; i < 100; i++)
				{
					if ((1 << i & cullingMask) != 0)
					{
						obj.SetLayerWidthChildren(i);
						break;
					}
				}
			}
		}

