public int RobInternal(List<int> nums)
{
      var max = 0;

      var dp = new Dictionary<int, int>();
      dp[-1] = 0;
      dp[-2] = 0;
      dp[-3] = 0;

      for (int i = 0; i < nums.Count; i++)
      {
        dp[i] = nums[i] + Math.Max(dp[i - 2], dp[i - 3]);
        max = Math.Max(max, dp[i]);
      }

      return max;
    }

